    TRY_CAST(NULLIF(trim(`distribution_facility_id`), '') AS BIGINT) AS `distribution_facility_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`pricing_agreement_id`), '') AS BIGINT) AS `pricing_agreement_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`retail_store_id`), '') AS BIGINT) AS `retail_store_id`,
    TRY_CAST(NULLIF(trim(`sales_rep_id`), '') AS BIGINT) AS `sales_rep_id`,
    TRY_CAST(NULLIF(trim(`supply_network_node_id`), '') AS BIGINT) AS `supply_network_node_id`,
    TRY_CAST(NULLIF(trim(`territory_id`), '') AS BIGINT) AS `territory_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    COALESCE(try_to_date(trim(`actual_delivery_date`), 'yyyy-MM-dd'), try_to_date(trim(`actual_delivery_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`actual_delivery_date`) AS DATE)) AS `actual_delivery_date`,
    COALESCE(try_to_timestamp(trim(`approved_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`approved_timestamp`) AS TIMESTAMP)) AS `approved_timestamp`,
    NULLIF(trim(`cancellation_reason`), '') AS `cancellation_reason`,
    CASE lower(trim(`channel_type`))
      WHEN 'retail' THEN 'retail'
      WHEN 'wholesale' THEN 'wholesale'
      WHEN 'dtc' THEN 'dtc'
      WHEN 'ecommerce' THEN 'ecommerce'
      WHEN 'distributor' THEN 'distributor'
      ELSE NULLIF(trim(`channel_type`), '')
    END AS `channel_type`,
    TRY_CAST(NULLIF(trim(`cogs_amount`), '') AS DECIMAL(18,2)) AS `cogs_amount`,
    COALESCE(try_to_date(trim(`confirmed_delivery_date`), 'yyyy-MM-dd'), try_to_date(trim(`confirmed_delivery_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`confirmed_delivery_date`) AS DATE)) AS `confirmed_delivery_date`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    TRY_CAST(NULLIF(trim(`discount_amount`), '') AS DECIMAL(18,2)) AS `discount_amount`,
    NULLIF(trim(`distribution_channel`), '') AS `distribution_channel`,
    NULLIF(trim(`division`), '') AS `division`,
    TRY_CAST(NULLIF(trim(`freight_amount`), '') AS DECIMAL(18,2)) AS `freight_amount`,
    TRY_CAST(NULLIF(trim(`gross_margin_amount`), '') AS DECIMAL(18,2)) AS `gross_margin_amount`,
    NULLIF(trim(`incoterm`), '') AS `incoterm`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    COALESCE(try_to_date(trim(`order_date`), 'yyyy-MM-dd'), try_to_date(trim(`order_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`order_date`) AS DATE)) AS `order_date`,
    NULLIF(trim(`order_number`), '') AS `order_number`,
    NULLIF(trim(`order_status`), '') AS `order_status`,
    CASE lower(trim(`order_type`))
      WHEN 'standard' THEN 'standard'
      WHEN 'rush' THEN 'rush'
      WHEN 'drop_ship' THEN 'drop_ship'
      WHEN 'direct_store_delivery' THEN 'direct_store_delivery'
      WHEN 'promotional' THEN 'promotional'
      WHEN 'sample' THEN 'sample'
      ELSE NULLIF(trim(`order_type`), '')
    END AS `order_type`,
    CASE lower(trim(`otif_status`))
      WHEN 'on_time_in_full' THEN 'on_time_in_full'
      WHEN 'late' THEN 'late'
      WHEN 'partial' THEN 'partial'
      WHEN 'not_applicable' THEN 'not_applicable'
      ELSE NULLIF(trim(`otif_status`), '')
    END AS `otif_status`,
    NULLIF(trim(`payment_terms`), '') AS `payment_terms`,
    CASE lower(trim(`priority`))
      WHEN 'standard' THEN 'standard'
      WHEN 'high' THEN 'high'
      WHEN 'urgent' THEN 'urgent'
      WHEN 'critical' THEN 'critical'
      ELSE NULLIF(trim(`priority`), '')
    END AS `priority`,
    NULLIF(trim(`purchase_order_number`), '') AS `purchase_order_number`,
    COALESCE(try_to_date(trim(`requested_delivery_date`), 'yyyy-MM-dd'), try_to_date(trim(`requested_delivery_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`requested_delivery_date`) AS DATE)) AS `requested_delivery_date`,
    NULLIF(trim(`sales_office`), '') AS `sales_office`,
    NULLIF(trim(`sales_organization`), '') AS `sales_organization`,
    NULLIF(trim(`sap_sd_document_number`), '') AS `sap_sd_document_number`,
    CASE lower(trim(`shipping_method`))
      WHEN 'ground' THEN 'ground'
      WHEN 'air' THEN 'air'
      WHEN 'ocean' THEN 'ocean'
      WHEN 'rail' THEN 'rail'
      WHEN 'courier' THEN 'courier'
      WHEN 'dsd' THEN 'dsd'
      ELSE NULLIF(trim(`shipping_method`), '')
    END AS `shipping_method`,
    CASE lower(trim(`source`))
      WHEN 'web_portal' THEN 'web_portal'
      WHEN 'edi' THEN 'edi'
      WHEN 'sales_rep' THEN 'sales_rep'
      WHEN 'call_center' THEN 'call_center'
      WHEN 'mobile_app' THEN 'mobile_app'
      WHEN 'marketplace' THEN 'marketplace'
      ELSE NULLIF(trim(`source`), '')
    END AS `source`,
    NULLIF(trim(`special_instructions`), '') AS `special_instructions`,
    TRY_CAST(NULLIF(trim(`subtotal_amount`), '') AS DECIMAL(18,2)) AS `subtotal_amount`,
    TRY_CAST(NULLIF(trim(`tax_amount`), '') AS DECIMAL(18,2)) AS `tax_amount`,
    TRY_CAST(NULLIF(trim(`total_amount`), '') AS DECIMAL(18,2)) AS `total_amount`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.sales_order
)
SELECT *
FROM typed
QUALIFY `order_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `order_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- sales.invoice ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.sales_invoice (
  CONSTRAINT `invoice_id_not_null` EXPECT (`invoice_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: sales.invoice typed and cleaned, one row per invoice_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`invoice_id`), '') AS BIGINT) AS `invoice_id`,
    TRY_CAST(NULLIF(trim(`account_address_id`), '') AS BIGINT) AS `account_address_id`,
    TRY_CAST(NULLIF(trim(`company_code_id`), '') AS BIGINT) AS `company_code_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`pricing_agreement_id`), '') AS BIGINT) AS `pricing_agreement_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`retail_store_id`), '') AS BIGINT) AS `retail_store_id`,
    TRY_CAST(NULLIF(trim(`sales_order_id`), '') AS BIGINT) AS `sales_order_id`,
    TRY_CAST(NULLIF(trim(`shipment_id`), '') AS BIGINT) AS `shipment_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    COALESCE(try_to_date(trim(`billing_period_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`billing_period_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`billing_period_end_date`) AS DATE)) AS `billing_period_end_date`,
    COALESCE(try_to_date(trim(`billing_period_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`billing_period_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`billing_period_start_date`) AS DATE)) AS `billing_period_start_date`,
    CASE lower(trim(`billing_type`))
      WHEN 'standard' THEN 'standard'
      WHEN 'credit_memo' THEN 'credit_memo'
      WHEN 'debit_memo' THEN 'debit_memo'
      WHEN 'proforma' THEN 'proforma'
      WHEN 'intercompany' THEN 'intercompany'
      WHEN 'consignment' THEN 'consignment'
      ELSE NULLIF(trim(`billing_type`), '')
    END AS `billing_type`,
    COALESCE(try_to_timestamp(trim(`cancelled_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`cancelled_timestamp`) AS TIMESTAMP)) AS `cancelled_timestamp`,
    TRY_CAST(NULLIF(trim(`cost_of_goods_sold_amount`), '') AS DECIMAL(18,2)) AS `cost_of_goods_sold_amount`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    TRY_CAST(NULLIF(trim(`days_sales_outstanding`), '') AS INT) AS `days_sales_outstanding`,
    CASE WHEN lower(trim(`dispute_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`dispute_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `dispute_flag`,
    NULLIF(trim(`dispute_reason_code`), '') AS `dispute_reason_code`,
    NULLIF(trim(`distribution_channel_code`), '') AS `distribution_channel_code`,
    NULLIF(trim(`division_code`), '') AS `division_code`,
    COALESCE(try_to_date(trim(`due_date`), 'yyyy-MM-dd'), try_to_date(trim(`due_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`due_date`) AS DATE)) AS `due_date`,
    NULLIF(trim(`edi_document_number`), '') AS `edi_document_number`,
    CASE lower(trim(`edi_transmission_status`))
      WHEN 'not_applicable' THEN 'not_applicable'
      WHEN 'pending' THEN 'pending'
      WHEN 'transmitted' THEN 'transmitted'
      WHEN 'acknowledged' THEN 'acknowledged'
      WHEN 'rejected' THEN 'rejected'
      WHEN 'failed' THEN 'failed'
      ELSE NULLIF(trim(`edi_transmission_status`), '')
    END AS `edi_transmission_status`,
    TRY_CAST(NULLIF(trim(`freight_charge_amount`), '') AS DECIMAL(18,2)) AS `freight_charge_amount`,
    TRY_CAST(NULLIF(trim(`gross_amount`), '') AS DECIMAL(18,2)) AS `gross_amount`,
    TRY_CAST(NULLIF(trim(`gross_margin_amount`), '') AS DECIMAL(18,2)) AS `gross_margin_amount`,
    NULLIF(trim(`incoterm_code`), '') AS `incoterm_code`,
    COALESCE(try_to_date(trim(`invoice_date`), 'yyyy-MM-dd'), try_to_date(trim(`invoice_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`invoice_date`) AS DATE)) AS `invoice_date`,
    NULLIF(trim(`invoice_number`), '') AS `invoice_number`,
    NULLIF(trim(`invoice_status`), '') AS `invoice_status`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    TRY_CAST(NULLIF(trim(`net_amount`), '') AS DECIMAL(18,2)) AS `net_amount`,
    NULLIF(trim(`notes`), '') AS `notes`,
    TRY_CAST(NULLIF(trim(`outstanding_amount`), '') AS DECIMAL(18,2)) AS `outstanding_amount`,
    TRY_CAST(NULLIF(trim(`paid_amount`), '') AS DECIMAL(18,2)) AS `paid_amount`,
    NULLIF(trim(`payment_method`), '') AS `payment_method`,
    NULLIF(trim(`payment_reference_number`), '') AS `payment_reference_number`,
    CASE lower(trim(`payment_status`))
      WHEN 'unpaid' THEN 'unpaid'
      WHEN 'partially_paid' THEN 'partially_paid'
      WHEN 'paid' THEN 'paid'
      WHEN 'overpaid' THEN 'overpaid'
      WHEN 'written_off' THEN 'written_off'
      ELSE NULLIF(trim(`payment_status`), '')
    END AS `payment_status`,
    NULLIF(trim(`payment_terms_code`), '') AS `payment_terms_code`,
    NULLIF(trim(`purchase_order_number`), '') AS `purchase_order_number`,
    CASE lower(trim(`revenue_recognition_category`))
      WHEN 'point_in_time' THEN 'point_in_time'
      WHEN 'over_time' THEN 'over_time'
      WHEN 'deferred' THEN 'deferred'
      WHEN 'subscription' THEN 'subscription'
      WHEN 'service' THEN 'service'
      ELSE NULLIF(trim(`revenue_recognition_category`), '')
    END AS `revenue_recognition_category`,
    NULLIF(trim(`sales_organization_code`), '') AS `sales_organization_code`,
    TRY_CAST(NULLIF(trim(`tax_amount`), '') AS DECIMAL(18,2)) AS `tax_amount`,
    TRY_CAST(NULLIF(trim(`trade_discount_amount`), '') AS DECIMAL(18,2)) AS `trade_discount_amount`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.sales_invoice
)
SELECT *
FROM typed
QUALIFY `invoice_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `invoice_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- sales.pricing_agreement ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.sales_pricing_agreement (
  CONSTRAINT `pricing_agreement_id_not_null` EXPECT (`pricing_agreement_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: sales.pricing_agreement typed and cleaned, one row per pricing_agreement_id (latest modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`pricing_agreement_id`), '') AS BIGINT) AS `pricing_agreement_id`,
    TRY_CAST(NULLIF(trim(`brand_id`), '') AS BIGINT) AS `brand_id`,
    TRY_CAST(NULLIF(trim(`funding_agreement_id`), '') AS BIGINT) AS `funding_agreement_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`hierarchy_id`), '') AS BIGINT) AS `hierarchy_id`,
    TRY_CAST(NULLIF(trim(`price_list_id`), '') AS BIGINT) AS `price_list_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`rep_id`), '') AS BIGINT) AS `rep_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`specification_id`), '') AS BIGINT) AS `specification_id`,
    TRY_CAST(NULLIF(trim(`supplier_id`), '') AS BIGINT) AS `supplier_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    TRY_CAST(NULLIF(trim(`trade_promotion_id`), '') AS BIGINT) AS `trade_promotion_id`,
    NULLIF(trim(`agreement_name`), '') AS `agreement_name`,
    NULLIF(trim(`agreement_number`), '') AS `agreement_number`,
    CASE lower(trim(`agreement_type`))
      WHEN 'standard' THEN 'standard'
      WHEN 'volume_tiered' THEN 'volume_tiered'
      WHEN 'promotional' THEN 'promotional'
      WHEN 'rebate' THEN 'rebate'
      WHEN 'contract' THEN 'contract'
      WHEN 'spot' THEN 'spot'
      ELSE NULLIF(trim(`agreement_type`), '')
    END AS `agreement_type`,
    CASE lower(trim(`approval_status`))
      WHEN 'not_submitted' THEN 'not_submitted'
      WHEN 'pending' THEN 'pending'
      WHEN 'approved' THEN 'approved'
      WHEN 'rejected' THEN 'rejected'
      ELSE NULLIF(trim(`approval_status`), '')
    END AS `approval_status`,
    NULLIF(trim(`approved_by`), '') AS `approved_by`,
    COALESCE(try_to_date(trim(`approved_date`), 'yyyy-MM-dd'), try_to_date(trim(`approved_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`approved_date`) AS DATE)) AS `approved_date`,
    CASE WHEN lower(trim(`auto_renewal_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`auto_renewal_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `auto_renewal_flag`,
    TRY_CAST(NULLIF(trim(`base_list_price`), '') AS DECIMAL(18,4)) AS `base_list_price`,
    NULLIF(trim(`contract_document_reference`), '') AS `contract_document_reference`,
    TRY_CAST(NULLIF(trim(`contracted_net_price`), '') AS DECIMAL(18,4)) AS `contracted_net_price`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    TRY_CAST(NULLIF(trim(`discount_percentage`), '') AS DECIMAL(5,2)) AS `discount_percentage`,
    NULLIF(trim(`distribution_channel`), '') AS `distribution_channel`,
    NULLIF(trim(`division`), '') AS `division`,
    COALESCE(try_to_date(trim(`effective_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_end_date`) AS DATE)) AS `effective_end_date`,
    COALESCE(try_to_date(trim(`effective_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_start_date`) AS DATE)) AS `effective_start_date`,
    NULLIF(trim(`geographic_scope`), '') AS `geographic_scope`,
    TRY_CAST(NULLIF(trim(`minimum_order_quantity`), '') AS DECIMAL(15,3)) AS `minimum_order_quantity`,
    TRY_CAST(NULLIF(trim(`minimum_order_value`), '') AS DECIMAL(18,2)) AS `minimum_order_value`,
    NULLIF(trim(`modified_by`), '') AS `modified_by`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    TRY_CAST(NULLIF(trim(`msrp_price`), '') AS DECIMAL(18,4)) AS `msrp_price`,
    NULLIF(trim(`notes`), '') AS `notes`,
    NULLIF(trim(`payment_terms`), '') AS `payment_terms`,
    CASE WHEN lower(trim(`price_protection_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`price_protection_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `price_protection_flag`,
    CASE lower(trim(`pricing_agreement_status`))
      WHEN 'draft' THEN 'draft'
      WHEN 'pending_approval' THEN 'pending_approval'
      WHEN 'active' THEN 'active'
      WHEN 'suspended' THEN 'suspended'
      WHEN 'expired' THEN 'expired'
      WHEN 'terminated' THEN 'terminated'
      ELSE NULLIF(trim(`pricing_agreement_status`), '')
    END AS `pricing_agreement_status`,
    CASE lower(trim(`pricing_tier`))
      WHEN 'tier_1' THEN 'tier_1'
      WHEN 'tier_2' THEN 'tier_2'
      WHEN 'tier_3' THEN 'tier_3'
      WHEN 'tier_4' THEN 'tier_4'
      WHEN 'tier_5' THEN 'tier_5'
      WHEN 'custom' THEN 'custom'
      ELSE NULLIF(trim(`pricing_tier`), '')
    END AS `pricing_tier`,
    CASE lower(trim(`product_scope`))
      WHEN 'all_products' THEN 'all_products'
      WHEN 'product_category' THEN 'product_category'
      WHEN 'specific_skus' THEN 'specific_skus'
      WHEN 'brand' THEN 'brand'
      ELSE NULLIF(trim(`product_scope`), '')
    END AS `product_scope`,
    TRY_CAST(NULLIF(trim(`promotional_allowance`), '') AS DECIMAL(18,2)) AS `promotional_allowance`,
    TRY_CAST(NULLIF(trim(`rebate_amount`), '') AS DECIMAL(18,2)) AS `rebate_amount`,
    TRY_CAST(NULLIF(trim(`rebate_percentage`), '') AS DECIMAL(5,2)) AS `rebate_percentage`,
    TRY_CAST(NULLIF(trim(`rsp_price`), '') AS DECIMAL(18,4)) AS `rsp_price`,
    NULLIF(trim(`sales_organization`), '') AS `sales_organization`,
    TRY_CAST(NULLIF(trim(`volume_threshold_quantity`), '') AS DECIMAL(15,3)) AS `volume_threshold_quantity`,
    NULLIF(trim(`volume_threshold_uom`), '') AS `volume_threshold_uom`,
    NULLIF(trim(`created_by`), '') AS `created_by`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.sales_pricing_agreement
)
SELECT *
FROM typed
QUALIFY `pricing_agreement_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `pricing_agreement_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- sales.pos_transaction ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.sales_pos_transaction (
  CONSTRAINT `pos_transaction_id_not_null` EXPECT (`pos_transaction_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: sales.pos_transaction typed and cleaned, one row per pos_transaction_id (latest _ingested_at wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`pos_transaction_id`), '') AS BIGINT) AS `pos_transaction_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`order_id`), '') AS BIGINT) AS `order_id`,
    TRY_CAST(NULLIF(trim(`promoted_price_id`), '') AS BIGINT) AS `promoted_price_id`,
    TRY_CAST(NULLIF(trim(`retail_store_id`), '') AS BIGINT) AS `retail_store_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    CASE WHEN lower(trim(`acv_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`acv_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `acv_flag`,
    CASE WHEN lower(trim(`baseline_sales_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`baseline_sales_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `baseline_sales_flag`,
    NULLIF(trim(`channel_type`), '') AS `channel_type`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    TRY_CAST(NULLIF(trim(`data_quality_score`), '') AS DECIMAL(5,2)) AS `data_quality_score`,
    CASE lower(trim(`data_source`))
      WHEN 'nielsen_iq' THEN 'nielsen_iq'
      WHEN 'iri_circana' THEN 'iri_circana'
      WHEN 'retailer_edi' THEN 'retailer_edi'
      WHEN 'retailer_portal' THEN 'retailer_portal'
      WHEN 'tradeedge' THEN 'tradeedge'
      WHEN 'internal' THEN 'internal'
      ELSE NULLIF(trim(`data_source`), '')
    END AS `data_source`,
    NULLIF(trim(`data_source_file_code`), '') AS `data_source_file_code`,
    TRY_CAST(NULLIF(trim(`discount_amount`), '') AS DECIMAL(18,2)) AS `discount_amount`,
    NULLIF(trim(`ean`), '') AS `ean`,
    TRY_CAST(NULLIF(trim(`extended_retail_value`), '') AS DECIMAL(18,2)) AS `extended_retail_value`,
    NULLIF(trim(`gtin`), '') AS `gtin`,
    NULLIF(trim(`market_name`), '') AS `market_name`,
    NULLIF(trim(`notes`), '') AS `notes`,
    CASE WHEN lower(trim(`out_of_stock_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`out_of_stock_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `out_of_stock_flag`,
    COALESCE(try_to_timestamp(trim(`processed_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`processed_timestamp`) AS TIMESTAMP)) AS `processed_timestamp`,
    NULLIF(trim(`product_description`), '') AS `product_description`,
    CASE WHEN lower(trim(`promotional_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`promotional_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `promotional_flag`,
    COALESCE(try_to_timestamp(trim(`received_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`received_timestamp`) AS TIMESTAMP)) AS `received_timestamp`,
    CASE lower(trim(`reporting_period`))
      WHEN 'daily' THEN 'daily'
      WHEN 'weekly' THEN 'weekly'
      WHEN 'monthly' THEN 'monthly'
      ELSE NULLIF(trim(`reporting_period`), '')
    END AS `reporting_period`,
    TRY_CAST(NULLIF(trim(`retail_selling_price`), '') AS DECIMAL(18,4)) AS `retail_selling_price`,
    NULLIF(trim(`retailer_name`), '') AS `retailer_name`,
    NULLIF(trim(`sku`), '') AS `sku`,
    NULLIF(trim(`store_city`), '') AS `store_city`,
    NULLIF(trim(`store_country_code`), '') AS `store_country_code`,
    NULLIF(trim(`store_format`), '') AS `store_format`,
    NULLIF(trim(`store_name`), '') AS `store_name`,
    NULLIF(trim(`store_postal_code`), '') AS `store_postal_code`,
    NULLIF(trim(`store_state_province`), '') AS `store_state_province`,
    COALESCE(try_to_date(trim(`transaction_date`), 'yyyy-MM-dd'), try_to_date(trim(`transaction_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`transaction_date`) AS DATE)) AS `transaction_date`,
    NULLIF(trim(`transaction_number`), '') AS `transaction_number`,
    COALESCE(try_to_timestamp(trim(`transaction_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`transaction_timestamp`) AS TIMESTAMP)) AS `transaction_timestamp`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    TRY_CAST(NULLIF(trim(`units_sold`), '') AS DECIMAL(18,3)) AS `units_sold`,
    NULLIF(trim(`upc`), '') AS `upc`,
    COALESCE(try_to_date(trim(`week_ending_date`), 'yyyy-MM-dd'), try_to_date(trim(`week_ending_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`week_ending_date`) AS DATE)) AS `week_ending_date`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.sales_pos_transaction
)
SELECT *
FROM typed
QUALIFY `pos_transaction_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `pos_transaction_id` ORDER BY _ingested_at DESC) = 1;

-- sales.return_order ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.sales_return_order (
  CONSTRAINT `return_order_id_not_null` EXPECT (`return_order_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: sales.return_order typed and cleaned, one row per return_order_id (latest modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`return_order_id`), '') AS BIGINT) AS `return_order_id`,
    TRY_CAST(NULLIF(trim(`batch_record_id`), '') AS BIGINT) AS `batch_record_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`inbound_receipt_id`), '') AS BIGINT) AS `inbound_receipt_id`,
    TRY_CAST(NULLIF(trim(`invoice_id`), '') AS BIGINT) AS `invoice_id`,
    TRY_CAST(NULLIF(trim(`originating_sales_order_id`), '') AS BIGINT) AS `originating_sales_order_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`product_complaint_id`), '') AS BIGINT) AS `product_complaint_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`retail_store_id`), '') AS BIGINT) AS `retail_store_id`,
    TRY_CAST(NULLIF(trim(`return_distribution_facility_id`), '') AS BIGINT) AS `return_distribution_facility_id`,
    TRY_CAST(NULLIF(trim(`return_network_node_id`), '') AS BIGINT) AS `return_network_node_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    TRY_CAST(NULLIF(trim(`adjustment_amount`), '') AS DECIMAL(15,2)) AS `adjustment_amount`,
    NULLIF(trim(`carrier_name`), '') AS `carrier_name`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    COALESCE(try_to_date(trim(`credit_memo_issued_date`), 'yyyy-MM-dd'), try_to_date(trim(`credit_memo_issued_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`credit_memo_issued_date`) AS DATE)) AS `credit_memo_issued_date`,
    COALESCE(try_to_date(trim(`credit_memo_posted_date`), 'yyyy-MM-dd'), try_to_date(trim(`credit_memo_posted_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`credit_memo_posted_date`) AS DATE)) AS `credit_memo_posted_date`,
    NULLIF(trim(`credit_memo_status`), '') AS `credit_memo_status`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    CASE WHEN lower(trim(`customer_responsible_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`customer_responsible_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `customer_responsible_flag`,
    NULLIF(trim(`disposition_instruction`), '') AS `disposition_instruction`,
    NULLIF(trim(`distribution_channel`), '') AS `distribution_channel`,
    NULLIF(trim(`division`), '') AS `division`,
    COALESCE(try_to_date(trim(`goods_received_date`), 'yyyy-MM-dd'), try_to_date(trim(`goods_received_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`goods_received_date`) AS DATE)) AS `goods_received_date`,
    COALESCE(try_to_date(trim(`inspection_completed_date`), 'yyyy-MM-dd'), try_to_date(trim(`inspection_completed_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`inspection_completed_date`) AS DATE)) AS `inspection_completed_date`,
    NULLIF(trim(`inspector_name`), '') AS `inspector_name`,
    NULLIF(trim(`lot_batch_number`), '') AS `lot_batch_number`,
    NULLIF(trim(`modified_by`), '') AS `modified_by`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    NULLIF(trim(`notes`), '') AS `notes`,
    TRY_CAST(NULLIF(trim(`original_unit_price`), '') AS DECIMAL(15,2)) AS `original_unit_price`,
    CASE lower(trim(`quality_inspection_result`))
      WHEN 'passed' THEN 'passed'
      WHEN 'failed' THEN 'failed'
      WHEN 'partial' THEN 'partial'
      WHEN 'not_inspected' THEN 'not_inspected'
      ELSE NULLIF(trim(`quality_inspection_result`), '')
    END AS `quality_inspection_result`,
    TRY_CAST(NULLIF(trim(`restocking_fee_amount`), '') AS DECIMAL(15,2)) AS `restocking_fee_amount`,
    COALESCE(try_to_date(trim(`return_authorization_date`), 'yyyy-MM-dd'), try_to_date(trim(`return_authorization_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`return_authorization_date`) AS DATE)) AS `return_authorization_date`,
    NULLIF(trim(`return_authorization_number`), '') AS `return_authorization_number`,
    CASE lower(trim(`return_order_type`))
      WHEN 'retail_account_return' THEN 'retail_account_return'
      WHEN 'distributor_return' THEN 'distributor_return'
      WHEN 'dtc_consumer_return' THEN 'dtc_consumer_return'
      WHEN 'wholesale_return' THEN 'wholesale_return'
      ELSE NULLIF(trim(`return_order_type`), '')
    END AS `return_order_type`,
    NULLIF(trim(`return_reason_code`), '') AS `return_reason_code`,
    NULLIF(trim(`return_reason_description`), '') AS `return_reason_description`,
    COALESCE(try_to_date(trim(`return_request_date`), 'yyyy-MM-dd'), try_to_date(trim(`return_request_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`return_request_date`) AS DATE)) AS `return_request_date`,
    TRY_CAST(NULLIF(trim(`return_shipping_cost`), '') AS DECIMAL(15,2)) AS `return_shipping_cost`,
    NULLIF(trim(`return_status`), '') AS `return_status`,
    TRY_CAST(NULLIF(trim(`return_value_gross`), '') AS DECIMAL(15,2)) AS `return_value_gross`,
    TRY_CAST(NULLIF(trim(`return_value_net`), '') AS DECIMAL(15,2)) AS `return_value_net`,
    TRY_CAST(NULLIF(trim(`returned_quantity`), '') AS DECIMAL(15,3)) AS `returned_quantity`,
    NULLIF(trim(`returned_quantity_uom`), '') AS `returned_quantity_uom`,
    NULLIF(trim(`sales_organization`), '') AS `sales_organization`,
    NULLIF(trim(`tracking_number`), '') AS `tracking_number`,
    NULLIF(trim(`warehouse_location_code`), '') AS `warehouse_location_code`,
    NULLIF(trim(`created_by`), '') AS `created_by`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.sales_return_order
)
SELECT *
FROM typed
QUALIFY `return_order_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `return_order_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- sales.territory ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.sales_territory (
  CONSTRAINT `territory_id_not_null` EXPECT (`territory_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: sales.territory typed and cleaned, one row per territory_id (latest modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`territory_id`), '') AS BIGINT) AS `territory_id`,
    TRY_CAST(NULLIF(trim(`distribution_facility_id`), '') AS BIGINT) AS `distribution_facility_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`account_count`), '') AS INT) AS `account_count`,
    TRY_CAST(NULLIF(trim(`acv_coverage`), '') AS DECIMAL(15,2)) AS `acv_coverage`,
    TRY_CAST(NULLIF(trim(`annual_quota_amount`), '') AS DECIMAL(18,2)) AS `annual_quota_amount`,
    TRY_CAST(NULLIF(trim(`call_frequency_days`), '') AS INT) AS `call_frequency_days`,
    NULLIF(trim(`channel_assignment`), '') AS `channel_assignment`,
    NULLIF(trim(`code`), '') AS `code`,
    NULLIF(trim(`country_code`), '') AS `country_code`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`distribution_channel`), '') AS `distribution_channel`,
    NULLIF(trim(`district`), '') AS `district`,
    NULLIF(trim(`division`), '') AS `division`,
    CASE WHEN lower(trim(`dsd_eligible_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`dsd_eligible_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `dsd_eligible_flag`,
    CASE WHEN lower(trim(`edi_capability_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`edi_capability_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `edi_capability_flag`,
    COALESCE(try_to_date(trim(`effective_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_end_date`) AS DATE)) AS `effective_end_date`,
    COALESCE(try_to_date(trim(`effective_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_start_date`) AS DATE)) AS `effective_start_date`,
    NULLIF(trim(`geographic_scope`), '') AS `geographic_scope`,
    NULLIF(trim(`modified_by`), '') AS `modified_by`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    NULLIF(trim(`name`), '') AS `name`,
    NULLIF(trim(`notes`), '') AS `notes`,
    CASE WHEN lower(trim(`pog_compliance_required_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`pog_compliance_required_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `pog_compliance_required_flag`,
    NULLIF(trim(`postal_code_list`), '') AS `postal_code_list`,
    CASE lower(trim(`priority_tier`))
      WHEN 'tier_1' THEN 'tier_1'
      WHEN 'tier_2' THEN 'tier_2'
      WHEN 'tier_3' THEN 'tier_3'
      WHEN 'strategic' THEN 'strategic'
      WHEN 'standard' THEN 'standard'
      ELSE NULLIF(trim(`priority_tier`), '')
    END AS `priority_tier`,
    NULLIF(trim(`quota_currency_code`), '') AS `quota_currency_code`,
    NULLIF(trim(`region`), '') AS `region`,
    NULLIF(trim(`sales_organization`), '') AS `sales_organization`,
    NULLIF(trim(`state_province_list`), '') AS `state_province_list`,
    TRY_CAST(NULLIF(trim(`store_count`), '') AS INT) AS `store_count`,
    TRY_CAST(NULLIF(trim(`tdp_coverage`), '') AS INT) AS `tdp_coverage`,
    CASE lower(trim(`territory_status`))
      WHEN 'active' THEN 'active'
      WHEN 'inactive' THEN 'inactive'
      WHEN 'pending' THEN 'pending'
      WHEN 'suspended' THEN 'suspended'
      WHEN 'archived' THEN 'archived'
      ELSE NULLIF(trim(`territory_status`), '')
    END AS `territory_status`,
    CASE lower(trim(`territory_type`))
      WHEN 'field' THEN 'field'
      WHEN 'key_account' THEN 'key_account'
      WHEN 'national_account' THEN 'national_account'
      WHEN 'regional' THEN 'regional'
      WHEN 'district' THEN 'district'
      WHEN 'channel' THEN 'channel'
      ELSE NULLIF(trim(`territory_type`), '')
    END AS `territory_type`,
    NULLIF(trim(`trade_class`), '') AS `trade_class`,
    CASE WHEN lower(trim(`vmi_eligible_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`vmi_eligible_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `vmi_eligible_flag`,
    NULLIF(trim(`created_by`), '') AS `created_by`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.sales_territory
)
SELECT *
FROM typed
QUALIFY `territory_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `territory_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

