    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`territory_id`), '') AS BIGINT) AS `territory_id`,
    TRY_CAST(NULLIF(trim(`trade_promotion_id`), '') AS BIGINT) AS `trade_promotion_id`,
    NULLIF(trim(`badge_number`), '') AS `badge_number`,
    CASE lower(trim(`certification_status`))
      WHEN 'certified' THEN 'certified'
      WHEN 'pending' THEN 'pending'
      WHEN 'expired' THEN 'expired'
      WHEN 'not_required' THEN 'not_required'
      ELSE NULLIF(trim(`certification_status`), '')
    END AS `certification_status`,
    NULLIF(trim(`channel_specialization`), '') AS `channel_specialization`,
    NULLIF(trim(`commission_plan_code`), '') AS `commission_plan_code`,
