    TRY_CAST(NULLIF(trim(`current_quota_amount`), '') AS DECIMAL(18,2)) AS `current_quota_amount`,
    NULLIF(trim(`email_address`), '') AS `email_address`,
    NULLIF(trim(`first_name`), '') AS `first_name`,
    NULLIF(trim(`full_name`), '') AS `full_name`,
    COALESCE(try_to_date(trim(`hire_date`), 'yyyy-MM-dd'), try_to_date(trim(`hire_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`hire_date`) AS DATE)) AS `hire_date`,
    NULLIF(trim(`language_code`), '') AS `language_code`,
    COALESCE(try_to_date(trim(`last_certification_date`), 'yyyy-MM-dd'), try_to_date(trim(`last_certification_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`last_certification_date`) AS DATE)) AS `last_certification_date`,
    NULLIF(trim(`last_name`), '') AS `last_name`,
    COALESCE(try_to_date(trim(`last_performance_review_date`), 'yyyy-MM-dd'), try_to_date(trim(`last_performance_review_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`last_performance_review_date`) AS DATE)) AS `last_performance_review_date`,
    NULLIF(trim(`mobile_device_code`), '') AS `mobile_device_code`,
    NULLIF(trim(`mobile_phone`), '') AS `mobile_phone`,
    NULLIF(trim(`modified_by`), '') AS `modified_by`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    NULLIF(trim(`notes`), '') AS `notes`,
    CASE lower(trim(`performance_rating`))
      WHEN 'exceeds' THEN 'exceeds'
      WHEN 'meets' THEN 'meets'
      WHEN 'below' THEN 'below'
      WHEN 'new_hire' THEN 'new_hire'
      ELSE NULLIF(trim(`performance_rating`), '')
    END AS `performance_rating`,
    NULLIF(trim(`quota_currency_code`), '') AS `quota_currency_code`,
    CASE lower(trim(`quota_period`))
      WHEN 'monthly' THEN 'monthly'
      WHEN 'quarterly' THEN 'quarterly'
      WHEN 'annual' THEN 'annual'
      ELSE NULLIF(trim(`quota_period`), '')
    END AS `quota_period`,
    NULLIF(trim(`rep_number`), '') AS `rep_number`,
    CASE lower(trim(`rep_status`))
      WHEN 'active' THEN 'active'
      WHEN 'inactive' THEN 'inactive'
      WHEN 'on_leave' THEN 'on_leave'
      WHEN 'suspended' THEN 'suspended'
      WHEN 'terminated' THEN 'terminated'
      ELSE NULLIF(trim(`rep_status`), '')
    END AS `rep_status`,
    CASE lower(trim(`rep_type`))
      WHEN 'field_sales' THEN 'field_sales'
      WHEN 'key_account_manager' THEN 'key_account_manager'
      WHEN 'national_account_manager' THEN 'national_account_manager'
      WHEN 'inside_sales' THEN 'inside_sales'
      WHEN 'dsd_driver' THEN 'dsd_driver'
      WHEN 'regional_manager' THEN 'regional_manager'
      ELSE NULLIF(trim(`rep_type`), '')
    END AS `rep_type`,
    NULLIF(trim(`sales_group`), '') AS `sales_group`,
    NULLIF(trim(`sales_office`), '') AS `sales_office`,
    NULLIF(trim(`sales_organization`), '') AS `sales_organization`,
    NULLIF(trim(`sfa_user_code`), '') AS `sfa_user_code`,
    COALESCE(try_to_date(trim(`termination_date`), 'yyyy-MM-dd'), try_to_date(trim(`termination_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`termination_date`) AS DATE)) AS `termination_date`,
    CASE WHEN lower(trim(`vehicle_assigned`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`vehicle_assigned`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `vehicle_assigned`,
    NULLIF(trim(`created_by`), '') AS `created_by`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.sales_rep
)
SELECT *
FROM typed
QUALIFY `rep_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `rep_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- sales.price_list ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.sales_price_list (
  CONSTRAINT `price_list_id_not_null` EXPECT (`price_list_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: sales.price_list typed and cleaned, one row per price_list_id (latest modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`price_list_id`), '') AS BIGINT) AS `price_list_id`,
    TRY_CAST(NULLIF(trim(`superseded_by_price_list_id`), '') AS BIGINT) AS `superseded_by_price_list_id`,
    TRY_CAST(NULLIF(trim(`supplier_contract_id`), '') AS BIGINT) AS `supplier_contract_id`,
    CASE lower(trim(`approval_status`))
      WHEN 'not_submitted' THEN 'not_submitted'
      WHEN 'pending' THEN 'pending'
      WHEN 'approved' THEN 'approved'
      WHEN 'rejected' THEN 'rejected'
      ELSE NULLIF(trim(`approval_status`), '')
    END AS `approval_status`,
    NULLIF(trim(`approved_by`), '') AS `approved_by`,
    COALESCE(try_to_timestamp(trim(`approved_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`approved_timestamp`) AS TIMESTAMP)) AS `approved_timestamp`,
    NULLIF(trim(`code`), '') AS `code`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    NULLIF(trim(`description`), '') AS `description`,
    CASE lower(trim(`distribution_channel`))
      WHEN 'retail' THEN 'retail'
      WHEN 'wholesale' THEN 'wholesale'
      WHEN 'dtc' THEN 'dtc'
      WHEN 'ecommerce' THEN 'ecommerce'
      WHEN 'foodservice' THEN 'foodservice'
      WHEN 'institutional' THEN 'institutional'
      ELSE NULLIF(trim(`distribution_channel`), '')
    END AS `distribution_channel`,
    NULLIF(trim(`division`), '') AS `division`,
    COALESCE(try_to_date(trim(`effective_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_end_date`) AS DATE)) AS `effective_end_date`,
    COALESCE(try_to_date(trim(`effective_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_start_date`) AS DATE)) AS `effective_start_date`,
    NULLIF(trim(`external_reference_code`), '') AS `external_reference_code`,
    CASE WHEN lower(trim(`freight_inclusion_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`freight_inclusion_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `freight_inclusion_flag`,
    NULLIF(trim(`geographic_scope`), '') AS `geographic_scope`,
    NULLIF(trim(`incoterm`), '') AS `incoterm`,
    TRY_CAST(NULLIF(trim(`minimum_order_quantity`), '') AS DECIMAL(15,3)) AS `minimum_order_quantity`,
    NULLIF(trim(`modified_by`), '') AS `modified_by`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    NULLIF(trim(`moq_uom`), '') AS `moq_uom`,
    CASE WHEN lower(trim(`msrp_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`msrp_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `msrp_flag`,
    NULLIF(trim(`name`), '') AS `name`,
    NULLIF(trim(`notes`), '') AS `notes`,
    NULLIF(trim(`payment_terms`), '') AS `payment_terms`,
    CASE lower(trim(`price_basis`))
      WHEN 'list_price' THEN 'list_price'
      WHEN 'cost_plus' THEN 'cost_plus'
      WHEN 'market_based' THEN 'market_based'
      WHEN 'competitive' THEN 'competitive'
      WHEN 'value_based' THEN 'value_based'
      ELSE NULLIF(trim(`price_basis`), '')
    END AS `price_basis`,
    CASE lower(trim(`price_list_status`))
      WHEN 'draft' THEN 'draft'
      WHEN 'pending_approval' THEN 'pending_approval'
      WHEN 'active' THEN 'active'
      WHEN 'inactive' THEN 'inactive'
      WHEN 'expired' THEN 'expired'
      WHEN 'superseded' THEN 'superseded'
      ELSE NULLIF(trim(`price_list_status`), '')
    END AS `price_list_status`,
    CASE lower(trim(`price_list_type`))
      WHEN 'standard' THEN 'standard'
      WHEN 'promotional' THEN 'promotional'
      WHEN 'contract' THEN 'contract'
      WHEN 'channel_specific' THEN 'channel_specific'
      WHEN 'seasonal' THEN 'seasonal'
      WHEN 'clearance' THEN 'clearance'
      ELSE NULLIF(trim(`price_list_type`), '')
    END AS `price_list_type`,
    TRY_CAST(NULLIF(trim(`price_protection_days`), '') AS INT) AS `price_protection_days`,
    CASE WHEN lower(trim(`price_protection_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`price_protection_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `price_protection_flag`,
    CASE lower(trim(`price_rounding_rule`))
      WHEN 'none' THEN 'none'
      WHEN 'nearest_cent' THEN 'nearest_cent'
      WHEN 'nearest_nickel' THEN 'nearest_nickel'
      WHEN 'nearest_dime' THEN 'nearest_dime'
      WHEN 'nearest_dollar' THEN 'nearest_dollar'
      WHEN 'up_to_99' THEN 'up_to_99'
      ELSE NULLIF(trim(`price_rounding_rule`), '')
    END AS `price_rounding_rule`,
    NULLIF(trim(`price_uom`), '') AS `price_uom`,
    NULLIF(trim(`pricing_condition_type`), '') AS `pricing_condition_type`,
    CASE WHEN lower(trim(`rsp_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`rsp_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `rsp_flag`,
    NULLIF(trim(`sales_organization`), '') AS `sales_organization`,
    NULLIF(trim(`tax_classification`), '') AS `tax_classification`,
    NULLIF(trim(`trade_class`), '') AS `trade_class`,
    TRY_CAST(NULLIF(trim(`version_number`), '') AS INT) AS `version_number`,
    NULLIF(trim(`created_by`), '') AS `created_by`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.sales_price_list
)
SELECT *
FROM typed
QUALIFY `price_list_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `price_list_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- sales.price_list_item ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.sales_price_list_item (
  CONSTRAINT `price_list_item_id_not_null` EXPECT (`price_list_item_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: sales.price_list_item typed and cleaned, one row per price_list_item_id (latest modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`price_list_item_id`), '') AS BIGINT) AS `price_list_item_id`,
    TRY_CAST(NULLIF(trim(`price_list_id`), '') AS BIGINT) AS `price_list_id`,
    TRY_CAST(NULLIF(trim(`promoted_price_id`), '') AS BIGINT) AS `promoted_price_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    CASE lower(trim(`approval_status`))
      WHEN 'draft' THEN 'draft'
      WHEN 'pending' THEN 'pending'
      WHEN 'approved' THEN 'approved'
      WHEN 'rejected' THEN 'rejected'
      ELSE NULLIF(trim(`approval_status`), '')
    END AS `approval_status`,
    NULLIF(trim(`approved_by`), '') AS `approved_by`,
    COALESCE(try_to_timestamp(trim(`approved_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`approved_timestamp`) AS TIMESTAMP)) AS `approved_timestamp`,
    CASE lower(trim(`channel_type`))
      WHEN 'retail' THEN 'retail'
      WHEN 'wholesale' THEN 'wholesale'
      WHEN 'dtc' THEN 'dtc'
      WHEN 'ecommerce' THEN 'ecommerce'
      WHEN 'foodservice' THEN 'foodservice'
      WHEN 'export' THEN 'export'
      ELSE NULLIF(trim(`channel_type`), '')
    END AS `channel_type`,
    NULLIF(trim(`condition_type`), '') AS `condition_type`,
    TRY_CAST(NULLIF(trim(`cost_price`), '') AS DECIMAL(18,4)) AS `cost_price`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    NULLIF(trim(`customer_segment`), '') AS `customer_segment`,
    NULLIF(trim(`distribution_channel`), '') AS `distribution_channel`,
    NULLIF(trim(`division`), '') AS `division`,
    COALESCE(try_to_date(trim(`effective_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_end_date`) AS DATE)) AS `effective_end_date`,
    COALESCE(try_to_date(trim(`effective_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_start_date`) AS DATE)) AS `effective_start_date`,
    NULLIF(trim(`geographic_scope`), '') AS `geographic_scope`,
    NULLIF(trim(`gtin`), '') AS `gtin`,
    TRY_CAST(NULLIF(trim(`item_sequence`), '') AS INT) AS `item_sequence`,
    TRY_CAST(NULLIF(trim(`list_price`), '') AS DECIMAL(18,4)) AS `list_price`,
    TRY_CAST(NULLIF(trim(`margin_percentage`), '') AS DECIMAL(5,2)) AS `margin_percentage`,
    TRY_CAST(NULLIF(trim(`minimum_order_quantity`), '') AS DECIMAL(10,3)) AS `minimum_order_quantity`,
    NULLIF(trim(`modified_by`), '') AS `modified_by`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    NULLIF(trim(`moq_uom`), '') AS `moq_uom`,
    TRY_CAST(NULLIF(trim(`msrp_price`), '') AS DECIMAL(18,4)) AS `msrp_price`,
    NULLIF(trim(`notes`), '') AS `notes`,
    CASE WHEN lower(trim(`override_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`override_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `override_flag`,
    CASE lower(trim(`price_list_item_status`))
      WHEN 'active' THEN 'active'
      WHEN 'inactive' THEN 'inactive'
      WHEN 'pending' THEN 'pending'
      WHEN 'expired' THEN 'expired'
      WHEN 'superseded' THEN 'superseded'
      ELSE NULLIF(trim(`price_list_item_status`), '')
    END AS `price_list_item_status`,
    NULLIF(trim(`price_uom`), '') AS `price_uom`,
    TRY_CAST(NULLIF(trim(`pricing_unit_quantity`), '') AS DECIMAL(10,3)) AS `pricing_unit_quantity`,
    CASE WHEN lower(trim(`promotional_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`promotional_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `promotional_flag`,
    TRY_CAST(NULLIF(trim(`rsp_price`), '') AS DECIMAL(18,4)) AS `rsp_price`,
    NULLIF(trim(`sales_organization`), '') AS `sales_organization`,
    NULLIF(trim(`sap_condition_record_number`), '') AS `sap_condition_record_number`,
    CASE lower(trim(`scale_basis`))
      WHEN 'quantity' THEN 'quantity'
      WHEN 'value' THEN 'value'
      WHEN 'weight' THEN 'weight'
      WHEN 'volume' THEN 'volume'
      ELSE NULLIF(trim(`scale_basis`), '')
    END AS `scale_basis`,
    TRY_CAST(NULLIF(trim(`scale_quantity_from`), '') AS DECIMAL(10,3)) AS `scale_quantity_from`,
    TRY_CAST(NULLIF(trim(`scale_quantity_to`), '') AS DECIMAL(10,3)) AS `scale_quantity_to`,
    NULLIF(trim(`created_by`), '') AS `created_by`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.sales_price_list_item
)
SELECT *
FROM typed
QUALIFY `price_list_item_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `price_list_item_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- sales.assignment ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.sales_assignment (
  CONSTRAINT `assignment_id_not_null` EXPECT (`assignment_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: sales.assignment typed and cleaned, one row per assignment_id (latest modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`assignment_id`), '') AS BIGINT) AS `assignment_id`,
    TRY_CAST(NULLIF(trim(`rep_id`), '') AS BIGINT) AS `rep_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    NULLIF(trim(`assignment_role`), '') AS `assignment_role`,
    NULLIF(trim(`assignment_status`), '') AS `assignment_status`,
    TRY_CAST(NULLIF(trim(`call_frequency_days`), '') AS INT) AS `call_frequency_days`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    COALESCE(try_to_date(trim(`effective_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_end_date`) AS DATE)) AS `effective_end_date`,
    COALESCE(try_to_date(trim(`effective_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_start_date`) AS DATE)) AS `effective_start_date`,
    CASE WHEN lower(trim(`is_primary_rep`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_primary_rep`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_primary_rep`,
    NULLIF(trim(`modified_by`), '') AS `modified_by`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    NULLIF(trim(`created_by`), '') AS `created_by`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.sales_assignment
)
SELECT *
FROM typed
QUALIFY `assignment_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `assignment_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;
